   141|/* ─── Base Layer ──────────────────────────────────────────────────────────── */
   142|
   143|@layer base {
   144|  html, body, #root {
   145|    height: 100%;
   146|    margin: 0;
   147|    padding: 0;
   148|  }
   149|
   150|  html {
   151|    -webkit-text-size-adjust: 100%;
   152|    overflow-x: hidden;
   153|  }
   154|
   155|  body {
   156|    background-color: var(--bg-primary, #f5ede0);
   157|    color: var(--text-primary, #1a1008);
   158|    font-family: var(--font-primary, 'Noto Serif SC', serif);
   159|    position: relative;
   160|    -webkit-font-smoothing: antialiased;
   161|    transition: background-color 0.3s ease, color 0.3s ease;
   162|    overflow-x: hidden;
   163|    max-width: 100vw;
   164|  }
   165|
   166|  /* Hide scrollbars on horizontally scrollable elements */
   167|  .scroll-x-hidden {
   168|    scrollbar-width: none;
   169|    -ms-overflow-style: none;
   170|  }
   171|  .scroll-x-hidden::-webkit-scrollbar {
   172|    display: none;
   173|  }
   174|
   175|  /* Sci-fi grid background */
