   177|  [data-theme="neon-cyber"] body::before {
   178|    background-image:
   179|      linear-gradient(var(--board-line-glow) 1px, transparent 1px),
   180|      linear-gradient(90deg, var(--board-line-glow) 1px, transparent 1px);
   181|    background-size: 40px 40px;
   182|  }
   183|
   184|  body::before {
   185|    content: '';
